+        fs::write(ui.join(".cargo/config"), "[target.'cfg(unix)']\nrustflags = []\n").unwrap();
+        // Cargo uses the extensionless file when both names exist.
+        fs::write(ui.join(".cargo/config.toml"), "[profile.ignored]\ndebug = true\n").unwrap();
